// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function testFuzz_property(uint256 mintAmount, uint256 burnAmount) public {
        uint256 maxUint = type(uint256).max;
        vm.assume(mintAmount <= maxUint / 2);
        vm.assume(burnAmount <= mintAmount);
        vm.assume(mintAmount > 0);

        vm.startPrank(address(this));
        c.mintToken(address(this), mintAmount);

        uint256 balanceBefore = c.balanceOf(address(this));
        c.burn(burnAmount);
        uint256 balanceAfter = c.balanceOf(address(this));
        vm.stopPrank();

        assertTrue(balanceBefore - balanceAfter == burnAmount);
    }
}
